#!/usr/bin/env node
// Generates supabase/migrations/20260831170000_seed_templates.sql -- the five
// read-only templates (#61): the AIDD reference grid and the four sample
// profiles, as `is_template = true` rows with a fixed id each.
//
//   pnpm db:seed:templates        # regenerate after editing the sources
//   pnpm templates:check          # fail if the committed .sql is stale
//
// Sources: presets/aidd.json and test/fixtures/profiles/*. The generated file
// is idempotent (ON CONFLICT (id) DO UPDATE), so re-applying it -- a local
// `db reset`, or a manual re-run against Cloud -- restates the rows without
// duplicating. A plain `supabase db push` only applies a version once, so a
// *content* change to these templates that must reach an already-migrated DB
// needs a new migration (or the manual re-apply above).

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { readProfileFromDirectory } from '../dist/adapters/inbound/json-profile.js';
import { parseGrid, parseProfile } from '../dist/compose.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..');
const OUT = resolve(ROOT, 'supabase/migrations/20260831170000_seed_templates.sql');

// Fixed ids: idempotent upsert, and a stable target for "clone from template".
const GRID = { id: '61111111-0000-4000-8000-000000000001', name: 'AIDD reference' };
const PROFILES = [
  { dir: 'perceval', id: '61111111-0000-4000-8000-000000000011', name: 'Perceval' },
  { dir: 'bohort', id: '61111111-0000-4000-8000-000000000012', name: 'Bohort' },
  { dir: 'leodagan', id: '61111111-0000-4000-8000-000000000013', name: 'Léodagan' },
  { dir: 'arthur', id: '61111111-0000-4000-8000-000000000014', name: 'Arthur' },
];

const quote = (s) => `'${String(s).replace(/'/g, "''")}'`;
const jsonLiteral = (value) => quote(JSON.stringify(value));

function buildSeedSql() {
  const gridBody = JSON.parse(readFileSync(resolve(ROOT, 'presets/aidd.json'), 'utf8'));
  const gridCheck = parseGrid(gridBody);
  if (!gridCheck.ok) throw new Error(`presets/aidd.json does not parse: ${gridCheck.error.message}`);

  const profileRows = PROFILES.map(({ dir, id, name }) => {
    const read = readProfileFromDirectory(resolve(ROOT, 'test/fixtures/profiles', dir));
    if (!read.ok) throw new Error(`profile ${dir}: ${read.error.message}`);
    const body = JSON.parse(JSON.stringify(read.value));
    const check = parseProfile(body);
    if (!check.ok) throw new Error(`profile ${dir} body does not round-trip: ${check.error.message}`);
    return { id, name, body };
  });

  return [
    '-- #61: the known references as read-only templates (org_id NULL, is_template).',
    '-- GENERATED by scripts/build-template-seed.mjs from presets/aidd.json and',
    '-- test/fixtures/profiles/* -- edit those and re-run, do not hand-edit this file.',
    '-- Idempotent (fixed ids + ON CONFLICT DO UPDATE): a local db reset and a manual',
    '-- re-apply against Cloud both restate the rows. `pnpm templates:check` guards it.',
    '',
    'insert into public.grid (id, org_id, created_by, name, body, is_template) values',
    `  (${quote(GRID.id)}, null, null, ${quote(GRID.name)}, ${jsonLiteral(gridBody)}::jsonb, true)`,
    'on conflict (id) do update set name = excluded.name, body = excluded.body, updated_at = now();',
    '',
    'insert into public.profile (id, org_id, created_by, name, body, is_template) values',
    profileRows
      .map((r) => `  (${quote(r.id)}, null, null, ${quote(r.name)}, ${jsonLiteral(r.body)}::jsonb, true)`)
      .join(',\n'),
    'on conflict (id) do update set name = excluded.name, body = excluded.body, updated_at = now();',
    '',
  ].join('\n');
}

const sql = buildSeedSql();

if (process.argv.includes('--check')) {
  const current = readFileSync(OUT, 'utf8');
  if (current !== sql) {
    console.error(
      `${OUT} is stale -- run \`pnpm db:seed:templates\` after editing presets/aidd.json or test/fixtures/profiles/*.`,
    );
    process.exit(1);
  }
  console.log('template seed migration is in step with the sources');
} else {
  writeFileSync(OUT, sql);
  console.log(`wrote ${OUT}`);
  console.log(`  grid: ${GRID.name} (${GRID.id})`);
  for (const p of PROFILES) console.log(`  profile: ${p.name} (${p.id})`);
}
